import React from 'react';
import {
  Container,
  Typography,
  Box,
  Grid,
  Card,
  CardMedia,
  CardContent,
  Button,
  Chip,
  Alert,
  Skeleton
} from '@mui/material';
import { ShoppingCart, Favorite, Visibility } from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';

const ProductsPage = () => {
  const navigate = useNavigate();

  // Sample products (since we don't have backend connection yet)
  const sampleProducts = [
    {
      _id: '1',
      name: 'Premium Cotton T-Shirt',
      price: 29.99,
      images: ['https://images.unsplash.com/photo-1521572163474-6864f9cf17ab?w=400'],
      category: 'T-Shirts',
      description: 'Comfortable premium cotton t-shirt',
      inStock: true
    },
    {
      _id: '2',
      name: 'Classic Denim Jacket',
      price: 89.99,
      images: ['https://images.unsplash.com/photo-1544022613-e87ca75a784a?w=400'],
      category: 'Jackets',
      description: 'Timeless denim jacket for any occasion',
      inStock: true
    },
    {
      _id: '3',
      name: 'Elegant Summer Dress',
      price: 59.99,
      images: ['https://images.unsplash.com/photo-1515372039744-b8f02a3ae446?w=400'],
      category: 'Dresses',
      description: 'Light and airy summer dress',
      inStock: false
    },
    {
      _id: '4',
      name: 'Casual Sneakers',
      price: 79.99,
      images: ['https://images.unsplash.com/photo-1549298916-b41d501d3772?w=400'],
      category: 'Shoes',
      description: 'Comfortable casual sneakers for daily wear',
      inStock: true
    },
    {
      _id: '5',
      name: 'Leather Handbag',
      price: 129.99,
      images: ['https://images.unsplash.com/photo-1553062407-98eeb64c6a62?w=400'],
      category: 'Accessories',
      description: 'Premium leather handbag with spacious interior',
      inStock: true
    },
    {
      _id: '6',
      name: 'Wool Blend Sweater',
      price: 69.99,
      images: ['https://images.unsplash.com/photo-1576566588028-4147f3842f27?w=400'],
      category: 'Sweaters',
      description: 'Cozy wool blend sweater for cooler weather',
      inStock: true
    }
  ];

  const handleAddToCart = (product) => {
    // Placeholder for cart functionality
    console.log('Adding to cart:', product);
    // You would typically dispatch an action here
  };

  const handleViewProduct = (productId) => {
    navigate(`/products/${productId}`);
  };

  return (
    <Container maxWidth="xl" sx={{ py: 4 }}>
      {/* Page Header */}
      <Box sx={{ mb: 4 }}>
        <Typography variant="h3" gutterBottom fontWeight="bold">
          Our Products
        </Typography>
        <Typography variant="body1" color="text.secondary">
          Discover our curated collection of fashion items
        </Typography>
      </Box>

      {/* Notice about backend connection */}
      <Alert severity="info" sx={{ mb: 4 }}>
        <Typography variant="body2">
          <strong>Demo Mode:</strong> Showing sample products. Backend connection needed for full functionality.
        </Typography>
      </Alert>

      {/* Products Grid */}
      <Grid container spacing={3}>
        {sampleProducts.map((product) => (
          <Grid item xs={12} sm={6} md={4} lg={3} key={product._id}>
            <Card 
              sx={{ 
                height: '100%',
                display: 'flex',
                flexDirection: 'column',
                transition: 'transform 0.2s ease-in-out',
                '&:hover': {
                  transform: 'translateY(-4px)',
                  boxShadow: (theme) => theme.shadows[8]
                }
              }}
            >
              {/* Product Image */}
              <Box sx={{ position: 'relative' }}>
                <CardMedia
                  component="img"
                  height="250"
                  image={product.images[0]}
                  alt={product.name}
                  sx={{ objectFit: 'cover' }}
                />
                
                {/* Stock Status */}
                {!product.inStock && (
                  <Chip
                    label="Out of Stock"
                    color="error"
                    size="small"
                    sx={{
                      position: 'absolute',
                      top: 8,
                      left: 8
                    }}
                  />
                )}

                {/* Quick Actions */}
                <Box
                  sx={{
                    position: 'absolute',
                    top: 8,
                    right: 8,
                    display: 'flex',
                    flexDirection: 'column',
                    gap: 1,
                    opacity: 0,
                    transition: 'opacity 0.2s ease-in-out',
                    '.MuiCard-root:hover &': {
                      opacity: 1
                    }
                  }}
                >
                  <Button
                    variant="contained"
                    size="small"
                    sx={{ 
                      minWidth: 'auto', 
                      p: 1,
                      backgroundColor: 'rgba(255, 255, 255, 0.9)',
                      color: 'primary.main',
                      '&:hover': {
                        backgroundColor: 'white'
                      }
                    }}
                    onClick={() => handleViewProduct(product._id)}
                  >
                    <Visibility fontSize="small" />
                  </Button>
                  <Button
                    variant="contained"
                    size="small"
                    sx={{ 
                      minWidth: 'auto', 
                      p: 1,
                      backgroundColor: 'rgba(255, 255, 255, 0.9)',
                      color: 'error.main',
                      '&:hover': {
                        backgroundColor: 'white'
                      }
                    }}
                  >
                    <Favorite fontSize="small" />
                  </Button>
                </Box>
              </Box>

              {/* Product Info */}
              <CardContent sx={{ flexGrow: 1, display: 'flex', flexDirection: 'column' }}>
                <Typography variant="h6" gutterBottom fontWeight="bold" noWrap>
                  {product.name}
                </Typography>
                
                <Typography variant="body2" color="text.secondary" sx={{ mb: 1, flexGrow: 1 }}>
                  {product.description}
                </Typography>

                <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 2 }}>
                  <Chip 
                    label={product.category} 
                    variant="outlined" 
                    size="small"
                    color="primary"
                  />
                  <Typography variant="h6" fontWeight="bold" color="primary.main">
                    ${product.price}
                  </Typography>
                </Box>

                <Button
                  variant="contained"
                  fullWidth
                  startIcon={<ShoppingCart />}
                  disabled={!product.inStock}
                  onClick={() => handleAddToCart(product)}
                  sx={{ mt: 'auto' }}
                >
                  {product.inStock ? 'Add to Cart' : 'Out of Stock'}
                </Button>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>

      {/* Loading Skeleton (for when real API is connected) */}
      {false && (
        <Grid container spacing={3}>
          {Array.from({ length: 6 }).map((_, index) => (
            <Grid item xs={12} sm={6} md={4} lg={3} key={index}>
              <Card>
                <Skeleton variant="rectangular" height={250} />
                <CardContent>
                  <Skeleton variant="text" height={32} />
                  <Skeleton variant="text" height={20} width="80%" />
                  <Box sx={{ display: 'flex', justifyContent: 'space-between', mt: 2 }}>
                    <Skeleton variant="text" width="40%" />
                    <Skeleton variant="text" width="30%" />
                  </Box>
                  <Skeleton variant="rectangular" height={40} sx={{ mt: 2 }} />
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      )}

      {/* Empty State (for when no products) */}
      {sampleProducts.length === 0 && (
        <Box
          sx={{
            textAlign: 'center',
            py: 8
          }}
        >
          <Typography variant="h5" gutterBottom color="text.secondary">
            No products found
          </Typography>
          <Typography variant="body1" color="text.secondary">
            Check back later for new arrivals!
          </Typography>
        </Box>
      )}
    </Container>
  );
};

export default ProductsPage;
